import java.util.*;import java.nio.charset.StandardCharsets;
class RiverBankRepairTest{static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]args)throws Exception{int n=128;var e=new EnvironmentMap(EnvironmentMap.filled(n*n,82));e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];for(int z=0;z<n;z++)for(int x=58;x<70;x++){int i=z*n+x;e.height[i]=80;e.water[i]=110;e.river[i]=1;}var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVER_BANKS,0,0);var a=RiverBanks.apply(node,e,n,n,62,2024,0,0,()->false);var b=RiverBanks.apply(node,e,n,n,62,2024,0,0,()->false);check(Arrays.equals(a.height,b.height)&&Arrays.equals(a.material,b.material),"repeatability");for(int z=0;z<n;z++)for(int x=0;x<n;x++){int i=z*n+x;if(a.waterY(i,62)>Math.round(a.height[i])&&a.river[i]>.05){check(a.water[i]-a.height[i]<=5.01,"bounded water depth");for(int dx:new int[]{-1,1})if(x+dx>=0&&x+dx<n&&a.river[i+dx]==0)check(a.height[i+dx]>=a.waterY(i,62),"contained by dry bank");}}check(e.water[64*n+64]==110,"input unchanged");Set<Byte> mats=new HashSet<>();for(byte m:a.material)mats.add(m);check(mats.contains((byte)1)&&mats.contains((byte)7)&&mats.size()>=4,"varied riparian materials "+mats);
var seam=new EnvironmentMap(EnvironmentMap.filled(16*16,80));seam.water=EnvironmentMap.filled(256,62);seam.river=new float[256];for(int z=0;z<16;z++){int k=z*16+8;seam.height[k]=76;seam.water[k]=81;seam.river[k]=1;}float[] originalWater=seam.water.clone();RiverBanks.containWater(seam,16,62);check(Arrays.equals(originalWater,seam.water),"seam repair preserves river water");for(int z=0;z<16;z++)check(seam.height[z*16+7]>=81&&seam.height[z*16+9]>=81,"seams contained");
var lake=new EnvironmentMap(EnvironmentMap.filled(n*n,95));lake.water=EnvironmentMap.filled(n*n,62);lake.river=new float[n*n];lake.material=new byte[n*n];for(int z=10;z<118;z++)for(int x=10;x<118;x++){int i=z*n+x;lake.height[i]=60;lake.water[i]=90;if(x>61&&x<67)lake.river[i]=1;}check(RiverBanks.apply(node,lake,n,n,62,2024,0,0,()->false).water[64*n+64]==90,"deep lake preserved");
var coast=new TerrainGraph.Node(2,TerrainGraph.Type.COAST,0,0);coast.values.put("oceanOnly",1.0);var out=EnvironmentNodes.apply(coast,e,null,n,n,62,2024,()->false);check(out.material[64*n+75]==0,"no inland beach treatment");
var global=new EnvironmentMap(EnvironmentMap.filled(2048*2048,100));global.water=EnvironmentMap.filled(2048*2048,62);global.height[0]=80;global.water[0]=105;check(LargeWorldBuilder.sampleWater(global,2,0)==105,"wet water level not diluted with dry sea baseline");check(LargeWorldBuilder.sampleWater(global,7,0)==62,"dry side does not get floating water");
global.river=new float[2048*2048];global.river[64]=1;global.height[64]=80;global.water[64]=105;var edgeTile=new TerraForge.World(512,62,2024);Arrays.fill(edgeTile.height,100);LargeWorldBuilder.sealTileEdges(global,edgeTile,0,0);check(edgeTile.height[511]>=105,"region export seals cross-tile riverbank");
var w=new TerraForge.World(16,62,2024);Arrays.fill(w.height,90);w.environment.material=new byte[256];for(int i=0;i<256;i++)w.environment.material[i]=(byte)(10+i%4);byte[] chunk=TerraForge.chunk(w,0,0);String data=new String(chunk,StandardCharsets.ISO_8859_1);for(String block:RiverBanks.EXTRA_BLOCKS)check(data.contains("minecraft:"+block),"export material "+block);System.out.println("PASS: contained water, bounded depth, natural material mix, lake preservation, ocean-only beaches, wet-aware sampling and actual chunk materials");}}
